import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs['target_snapshot']
    cdc_events = inputs['cdc_events']
    watermark = inputs['watermark']

    # Determine watermark high_ts (apply only events strictly after it)
    if watermark is not None and len(watermark) > 0:
        high_ts = watermark['high_ts'].iloc[0]
    else:
        high_ts = None

    events = cdc_events.copy()
    if high_ts is not None:
        events = events[events['event_ts'] > high_ts]

    # Sort events per item in (event_ts, event_seq) order for sequential application
    events = events.sort_values(['item_id', 'event_ts', 'event_seq'])

    # Initialize state from the existing snapshot
    state = {}
    for _, row in target_snapshot.iterrows():
        state[row['item_id']] = {
            'exists': True,
            'qty': row['qty_on_hand'],
            'last_ts': row['last_event_ts'],
        }

    # Apply each event sequentially per item
    for _, ev in events.iterrows():
        item = ev['item_id']
        op = ev['op']
        qty_val = ev['qty']
        ts_val = ev['event_ts']

        if item not in state:
            state[item] = {'exists': False, 'qty': None, 'last_ts': None}
        s = state[item]

        if op == 'D':
            s['exists'] = False
            s['qty'] = None
            s['last_ts'] = None
        elif op == 'R':
            if s['exists']:
                s['qty'] = s['qty'] + qty_val
            else:
                s['qty'] = 0 + qty_val
                s['exists'] = True
            s['last_ts'] = ts_val
        elif op == 'A':
            s['qty'] = qty_val
            s['exists'] = True
            s['last_ts'] = ts_val
        # any unrecognized op is ignored (defensive, not expected per spec)

    rows = []
    for item, s in state.items():
        if s['exists']:
            rows.append({
                'item_id': item,
                'qty_on_hand': s['qty'],
                'last_event_ts': s['last_ts'],
            })

    new_snapshot = pd.DataFrame(rows, columns=['item_id', 'qty_on_hand', 'last_event_ts'])

    return {'new_snapshot': new_snapshot}
